    private EmptySlot[,] emptySlots;
    private List<Gem> movingGems;

    void Start()
    {
        InitializeGame();
    }

    void InitializeGame()
    {
        gems = new Gem[gridSizeX, gridSizeY];
        emptySlots = new EmptySlot[gridSizeX, gridSizeY];
        movingGems = new List<Gem>();

        for (int x = 0; x < gridSizeX; x++)
        {
            for (int y = 0; y < gridSizeY; y++)
            {
                if (Random.value > 0.5f)
                {
                    gems[x, y] = Instantiate(gemPrefab, new Vector3(x, y, 0), Quaternion.identity);
                    gems[x, y].GetComponent<Gem>().Setup(x, y);
                }
                else
                {
                    emptySlots[x, y] = Instantiate(emptySlotPrefab, new Vector3(x, y, 0), Quaternion.identity);
                    emptySlots[x, y].GetComponent<EmptySlot>().Setup(x, y);
                }
            }
        }

        UpdateGems();
    }

    void Update()
    {
        CheckForMatches();
    }

    void CheckForMatches()
    {
        for (int x = 0; x < gridSizeX; x++)
        {
            for (int y = 0; y < gridSizeY; y++)
            {
                if (gems[x, y] != null)
                {
                    Gem gem = gems[x, y];
                    if (gem.HasMatch())
                    {
                        gem.Destroy();
                    }
                }
            }
        }
    }
}
```
